        this.x = x;
        this.y = y;
    }

    set(x, y) {
        this.x = x;
        this.y = y;
    }

    add(other) {
        return new Point(this.x + other.x, this.y + other.y);
    }

    sub(other) {
        return new Point(this.x - other.x, this.y - other.y);
    }

    mul(value) {
        return new Point(this.x * value, this.y * value);
    }

    div(value) {
        return this.mul(1 / value);
    }

    rot90() {
        return new Point(-this.y, this.x);
    }
