    return new Point(b.x - a.x, b.y - a.y);
}

function dMult(a, b) {
    return a.x * b.x + a.y * b.y;
}

function xMult(a, b) {
    return a.x * b.y - a.y * b.x;
}

function VecMod(a) {
    return Math.sqrt(dMult(a, a));
}

function VecMod2(a) {
    return dMult(a, a);
}

function Corner2V(a, b) {
    return Math.abs(Math.acos(dMult(a, b) / VecMod(a) / VecMod(b)));
}

function VecUnit(a) {
    return a.div(VecMod(a));
}

function VRotate(v, alph) {
    const sa = Math.sin(alph);
    const ca = Math.cos(alph);
    return new Point(v.x * ca - v.y * sa, v.x * sa + v.y * ca);
}

function PRotate(p, o, alph) {
    return o.add(VRotate(PtoV(o, p), alph));
}

function GetVV(v) {
    return VRotate(v, pi / 2);
}

function ShadowPOnLine(p, a, b) {
    const ab = PtoV(a, b);
    const ap = PtoV(a, p);
    const projection = VecUnit(ab).mul(dMult(ab, ap)).div(VecMod(ab));
    return a.add(projection);
}

