    const ret = [];
    const t = ShadowPOnLine(o, a, b);
    const ot = PtoV(o, t);
    const distance = VecMod(ot);

    if (distance - r > eps) {
        return ret;
    }

    if (Math.abs(distance - r) < eps) {
        ret.push(t);
        return ret;
