    const lr = Math.sqrt(r * r - VecMod2(ot));
    const ta = t.add(VecUnit(PtoV(t, a)).mul(lr));
    const tb = t.add(VecUnit(PtoV(t, b)).mul(lr));
    ret.push(ta, tb);
    return ret;
