Vec VecUnit(Vec a){
	// a的单位向量
	return a / VecMod(a);
}
Vec VRotate(Vec v,double alph){
	// 获得v向量的逆时针旋转alph角度的向量
	double sa = sin(alph),ca = cos(alph);
	return Vec(v.x*ca - v.y*sa , v.x*sa + v.y*ca);
}
